import { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { Icon } from '@iconify/react';
import api from '../utils/api';
import toast from 'react-hot-toast';

export default function Scholars() {
  const [scholars, setScholars] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [showAddForm, setShowAddForm] = useState(false);
  const [formData, setFormData] = useState({
    name: '',
    nameArabic: '',
    title: '',
    biography: '',
    birthYear: '',
    deathYear: '',
    region: '',
    books: '',
    specialties: '',
    website: ''
  });
  const [image, setImage] = useState(null);

  useEffect(() => {
    fetchScholars();
  }, []);

  const fetchScholars = async () => {
    try {
      const { data } = await api.get('/scholars');
      setScholars(data || []);
    } catch (error) {
      setScholars([]);
    } finally {
      setLoading(false);
    }
  };

  const handleAddScholar = async (e) => {
    e.preventDefault();
    const form = new FormData();
    Object.keys(formData).forEach(key => form.append(key, formData[key]));
    if (image) form.append('image', image);

    try {
      await api.post('/scholars', form, {
        headers: { 'Content-Type': 'multipart/form-data' }
      });
      toast.success('Scholar added!');
      setShowAddForm(false);
      setFormData({ name: '', nameArabic: '', title: '', biography: '', birthYear: '', deathYear: '', region: '', books: '', specialties: '', website: '' });
      setImage(null);
      fetchScholars();
    } catch (error) {
      toast.error('Failed to add scholar');
    }
  };

  const filtered = scholars.filter(s => 
    search === '' || 
    s.name.toLowerCase().includes(search.toLowerCase()) ||
    s.region?.toLowerCase().includes(search.toLowerCase()) ||
    s.specialties?.some(sp => sp.toLowerCase().includes(search.toLowerCase()))
  );

  if (loading) {
    return (
      <div className="flex justify-center items-center h-96">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-green-600"></div>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      {/* Header */}
      <div className="text-center mb-12 p-12 bg-gradient-to-br from-green-50 to-yellow-50 dark:from-green-900 dark:to-yellow-900 rounded-2xl">
        <h1 className="text-4xl font-bold mb-4 text-green-700 dark:text-green-400">Islamic Scholars</h1>
        <p className="text-lg text-gray-600 dark:text-gray-400 max-w-2xl mx-auto">
          Learn about the great scholars who preserved and transmitted Islamic knowledge through the centuries
        </p>
      </div>

      {/* Search and Add */}
      <div className="flex flex-col md:flex-row gap-4 mb-8">
        <div className="flex-1 relative">
          <Icon icon="ph:magnifying-glass-duotone" className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
          <input type="text" placeholder="Search scholars by name, region, or specialty..." value={search}
            onChange={e => setSearch(e.target.value)}
            className="w-full pl-10 pr-4 py-3 rounded-xl border dark:bg-gray-800 dark:border-gray-600" />
        </div>
        <button onClick={() => setShowAddForm(!showAddForm)}
          className="bg-green-600 hover:bg-green-700 text-white px-6 py-3 rounded-xl font-semibold inline-flex items-center gap-2">
          <Icon icon={showAddForm ? 'ph:x-duotone' : 'ph:plus-duotone'} className="w-5 h-5" />
          {showAddForm ? 'Cancel' : 'Add Scholar'}
        </button>
      </div>

      {/* Add Form */}
      {showAddForm && (
        <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-lg p-6 mb-8">
          <h2 className="text-xl font-bold mb-4">Add New Scholar</h2>
          <form onSubmit={handleAddScholar} className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium mb-1">Name *</label>
              <input type="text" required value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})}
                className="w-full px-4 py-2 rounded-lg border dark:bg-gray-700 dark:border-gray-600" />
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">Name (Arabic)</label>
              <input type="text" value={formData.nameArabic} onChange={e => setFormData({...formData, nameArabic: e.target.value})}
                className="w-full px-4 py-2 rounded-lg border dark:bg-gray-700 dark:border-gray-600 arabic-text" />
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">Title</label>
              <input type="text" value={formData.title} onChange={e => setFormData({...formData, title: e.target.value})}
                className="w-full px-4 py-2 rounded-lg border dark:bg-gray-700 dark:border-gray-600" />
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">Region</label>
              <input type="text" value={formData.region} onChange={e => setFormData({...formData, region: e.target.value})}
                className="w-full px-4 py-2 rounded-lg border dark:bg-gray-700 dark:border-gray-600" />
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">Specialties (comma separated)</label>
              <input type="text" value={formData.specialties} onChange={e => setFormData({...formData, specialties: e.target.value})}
                className="w-full px-4 py-2 rounded-lg border dark:bg-gray-700 dark:border-gray-600" />
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">Image</label>
              <input type="file" accept="image/*" onChange={e => setImage(e.target.files[0])}
                className="w-full px-4 py-2 rounded-lg border dark:bg-gray-700 dark:border-gray-600" />
            </div>
            <div className="md:col-span-2">
              <button type="submit" className="bg-green-600 hover:bg-green-700 text-white px-6 py-2 rounded-lg font-semibold">
                Add Scholar
              </button>
            </div>
          </form>
        </div>
      )}

      {/* Scholars Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filtered.map(scholar => (
          <Link key={scholar._id} to={`/scholars/${scholar._id}`}
            className="bg-white dark:bg-gray-800 rounded-2xl shadow-lg hover:shadow-xl transition-all hover:-translate-y-1 overflow-hidden group">
            <div className="p-6">
              <div className="flex items-start gap-4">
                {scholar.image ? (
                  <img src={`http://localhost:5000${scholar.image}`} alt={scholar.name}
                    className="w-16 h-16 object-cover rounded-xl" />
                ) : (
                  <div className="w-16 h-16 bg-gradient-to-br from-green-400 to-green-600 rounded-xl flex items-center justify-center flex-shrink-0">
                    <Icon icon="ph:user-circle-duotone" className="w-8 h-8 text-white" />
                  </div>
                )}
                <div className="flex-1 min-w-0">
                  <h3 className="font-bold text-lg group-hover:text-green-600 transition-colors">{scholar.name}</h3>
                  {scholar.title && <p className="text-sm text-gray-500">{scholar.title}</p>}
                  {scholar.region && <p className="text-xs text-gray-400 mt-1">{scholar.region}</p>}
                </div>
              </div>
              {scholar.specialties?.length > 0 && (
                <div className="flex flex-wrap gap-1 mt-3">
                  {scholar.specialties.slice(0, 3).map((s, i) => (
                    <span key={i} className="px-2 py-0.5 rounded-full text-xs bg-green-100 text-green-700 dark:bg-green-900 dark:text-green-300">
                      {s}
                    </span>
                  ))}
                </div>
              )}
            </div>
          </Link>
        ))}
      </div>

      {filtered.length === 0 && (
        <div className="text-center py-16">
          <Icon icon="ph:users-duotone" className="w-20 h-20 mx-auto text-gray-300 mb-4" />
          <p className="text-gray-500 text-lg">No scholars found</p>
        </div>
      )}
    </div>
  );
}
